// Des: Task list load and save; re-exports store parts
// Flo: taskPath > read file > parse tasks > validate each > drop bad ones
// I/O: aa-auto-task.json beside exe (hand-edited, hostile) > Load{ aren, task, reje }; never errors on a bad file; latches in ~/.ac-auto-task/task-state
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const stor = @import("store");
const tkstorbase = @import("tk-stor-base.zig"); const tkstorvali = @import("tk-stor-vali.zig"); const tkstorchai = @import("tk-stor-chai.zig"); const tkstorstat = @import("tk-stor-stat.zig"); 
pub const CF = tkstorbase.CF; pub const CMDS_SCRI = tkstorbase.CMDS_SCRI; pub const ChaiStat = tkstorbase.ChaiStat; pub const DEFA_TMOZ_SECO = tkstorbase.DEFA_TMOZ_SECO; pub const FILE_NAME = tkstorbase.FILE_NAME; pub const Load = tkstorbase.Load; pub const MAXZ_CWDZ = tkstorbase.MAXZ_CWDZ; pub const MAXZ_FILE = tkstorbase.MAXZ_FILE; pub const MAXZ_IDSZ = tkstorbase.MAXZ_IDSZ; pub const MAXZ_LOCK = tkstorbase.MAXZ_LOCK; pub const MAXZ_PLUS_POOL = tkstorbase.MAXZ_PLUS_POOL; pub const MAXZ_RETR = tkstorbase.MAXZ_RETR; pub const MAXZ_RUNZ = tkstorbase.MAXZ_RUNZ; pub const MAXZ_TMOZ_SECO = tkstorbase.MAXZ_TMOZ_SECO; pub const NONE_SCHE = tkstorbase.NONE_SCHE; pub const PLUS_BIGZ = tkstorbase.PLUS_BIGZ; pub const PLUS_MAXZ = tkstorbase.PLUS_MAXZ; pub const Reje = tkstorbase.Reje; pub const STAT_DIRZ = tkstorbase.STAT_DIRZ; pub const TYPE_LIST = tkstorbase.TYPE_LIST; pub const Task = tkstorbase.Task; pub const WINZ_ONLY = tkstorbase.WINZ_ONLY; pub const autoIdenChec = tkstorbase.autoIdenChec; pub const chaiChec = tkstorbase.chaiChec; pub const idenVali = tkstorbase.idenVali; pub const norm = tkstorbase.norm; pub const scheNeed = tkstorbase.scheNeed; pub const taskPath = tkstorbase.taskPath; pub const typeChec = tkstorbase.typeChec; pub const winzOnlyChec = tkstorbase.winzOnlyChec; 
pub const plusRang = tkstorvali.plusRang; pub const vali = tkstorvali.vali; 
pub const chaiBadzDrop = tkstorchai.chaiBadzDrop; pub const chaiFind = tkstorchai.chaiFind; 
pub const chaiStatClea = tkstorstat.chaiStatClea; pub const chaiStatRead = tkstorstat.chaiStatRead; pub const chaiStatWrit = tkstorstat.chaiStatWrit; pub const fireLastRead = tkstorstat.fireLastRead; pub const fireLastWrit = tkstorstat.fireLastWrit; pub const onceFireClea = tkstorstat.onceFireClea; pub const onceFireMark = tkstorstat.onceFireMark; pub const onceStamRead = tkstorstat.onceStamRead; pub const statDirz = tkstorstat.statDirz; 
pub fn load(gpa: std.mem.Allocator, iozz: std.Io, root: []const u8) !Load { var aren = std.heap.ArenaAllocator.init(gpa); const allo = aren.allocator(); var outz: Load = .{ .aren = aren, .task = &.{}, .reje = &.{}, .rawz_okay = false }; const path = taskPath(allo, root) catch { outz.aren = aren; return outz; }; const body = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(MAXZ_FILE)) catch |erro| { if (erro != error.FileNotFound) std.debug.print("  warn: task file {s} unreadable ({t})\n", .{ path, erro }); outz.aren = aren; return outz; }; if (std.mem.trim(u8, body, " \t\r\n").len == 0) { outz.rawz_okay = true; outz.aren = aren; return outz; } const pars = std.json.parseFromSliceLeaky([]Task, allo, body, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch |erro| { std.debug.print("  warn: task file {s} is not valid JSON ({t})\n", .{ path, erro }); outz.aren = aren; return outz; }; outz.rawz_okay = true; var keep: std.ArrayList(Task) = .empty; var kidz: std.ArrayList(usize) = .empty; var badz: std.ArrayList(Reje) = .empty; for (pars, 0..) |item, indx| { var task = norm(item); if (task.run.len == 0 and !chaiChec(task) and idenVali(task.id) == null) { const scri = autoScriPath(allo, root) catch ""; const cmdz = autoRunz(allo, root, task.id) catch null; if (cmdz == null) { badz.append(allo, .{ .inde = indx, .iden = task.id, .whyz = "no run, and the id has characters not allowed for auto-run (use A-Z a-z 0-9 . _ -)" }) catch {}; continue; } if (!fileExis(iozz, scri)) { const whyz = std.fmt.allocPrint(allo, "no run, and {s} not found", .{scri}) catch "no run, and the cmds script is missing"; badz.append(allo, .{ .inde = indx, .iden = task.id, .whyz = whyz }) catch {}; continue; } task.run = cmdz.?; } if (vali(task)) |whyz| { badz.append(allo, .{ .inde = indx, .iden = task.id, .whyz = whyz }) catch {}; continue; } var dupz = false; for (keep.items) |kept| { if (std.mem.eql(u8, kept.id, task.id)) { dupz = true; break; } } if (dupz) { badz.append(allo, .{ .inde = indx, .iden = task.id, .whyz = "duplicate id" }) catch {}; continue; } keep.append(allo, task) catch continue; kidz.append(allo, indx) catch { _ = keep.pop(); }; } const scri_okay = if (autoScriPath(allo, root)) |scpa| fileExis(iozz, scpa) else |_| false; chaiBadzDrop(allo, &keep, &kidz, &badz, scri_okay); outz.task = keep.toOwnedSlice(allo) catch &.{}; outz.reje = badz.toOwnedSlice(allo) catch &.{}; outz.aren = aren; return outz; }
pub fn autoScriPath(allo: std.mem.Allocator, root: []const u8) ![]u8 { return std.fs.path.join(allo, &.{ root, CMDS_SCRI }); }
pub fn autoRunz(allo: std.mem.Allocator, root: []const u8, iden: []const u8) !?[]u8 { if (!autoIdenChec(iden)) return null; const scri = try autoScriPath(allo, root); defer allo.free(scri); const spac = std.mem.indexOfScalar(u8, scri, ' ') != null; if (builtin.os.tag == .windows) { if (std.mem.indexOfScalar(u8, scri, '"') != null) return null; if (spac) return try std.fmt.allocPrint(allo, "\"{s}\" {s}", .{ scri, iden }); return try std.fmt.allocPrint(allo, "{s} {s}", .{ scri, iden }); } if (std.mem.indexOfScalar(u8, scri, '\'') != null) return null; if (spac) return try std.fmt.allocPrint(allo, "bash '{s}' {s}", .{ scri, iden }); return try std.fmt.allocPrint(allo, "bash {s} {s}", .{ scri, iden }); }
fn fileExis(iozz: std.Io, path: []const u8) bool { _ = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch return false; return true; }
var save_sequ: std.atomic.Value(u32) = .init(0);
pub fn save(allo: std.mem.Allocator, iozz: std.Io, root: []const u8, body: []const u8) !void { const path = try taskPath(allo, root); const sequ = save_sequ.fetchAdd(1, .monotonic); const temp = try std.fmt.allocPrint(allo, "{s}.{d}.tmp", .{ path, sequ }); var file = try std.Io.Dir.cwd().createFile(iozz, temp, .{ .truncate = true, .read = true }); { errdefer file.close(iozz); try file.writePositionalAll(iozz, body, 0); file.sync(iozz) catch {}; } file.close(iozz); try std.Io.Dir.rename(.cwd(), temp, .cwd(), path, iozz); }
pub const jobzFileSet = tkstorbase.jobzFileSet;
pub fn mtimMsec(iozz: std.Io, root: []const u8) i128 { var buff: [std.fs.max_path_bytes]u8 = undefined; if (root.len + 1 + tkstorbase.jobzFile.len > buff.len) return 0; const path = std.fmt.bufPrint(&buff, "{s}{c}{s}", .{ root, std.fs.path.sep, tkstorbase.jobzFile }) catch return 0; const stat = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch return 0; return stat.mtime.toMilliseconds(); }
